parameters.jsCode:
return items[0].json.organic.map(o => {
  const title = o.title || "";
  const agentName = title.split(" - ")[0].trim();

  return {
    agent_name: agentName,
    zillow_url: o.link,
    snippet: o.snippet || ""
  };
});
